// src/pages/Opportunities.jsx
import React, { useState } from 'react';
import { MapPin, Briefcase, Clock, Award, Filter, Search } from 'lucide-react';

const Opportunities = () => {
  const [filterWilaya, setFilterWilaya] = useState('');
  const [filterTech, setFilterTech] = useState('');

  const algeriaWilayas = ["Constantine", "Algiers", "Oran", "Sétif", "Annaba"];
  const techs = ["ReactJS", "NodeJS", "Python", "Flutter", "Tailwind CSS"];

  const styles = {
    container: {
      backgroundColor: '#fdfbff',
      minHeight: '100vh',
      fontFamily: "'Segoe UI', Tahoma, sans-serif",
    },
    heroSection: {
      backgroundColor: '#c5a3d1',
      padding: '60px 20px',
      textAlign: 'center',
      color: 'white',
    },
    heroTitle: {
      fontSize: '42px',
      fontWeight: 'bold',
      marginBottom: '15px',
    },
    filterContainer: {
      backgroundColor: 'white',
      padding: '25px',
      borderRadius: '15px',
      boxShadow: '0 10px 30px rgba(0,0,0,0.05)',
      maxWidth: '1000px',
      margin: '-40px auto 40px auto',
      display: 'flex',
      flexWrap: 'wrap',
      gap: '20px',
      position: 'relative',
      zIndex: 10,
      alignItems: 'flex-end'
    },
    inputGroup: {
      flex: '1',
      minWidth: '200px',
    },
    label: {
      display: 'block',
      fontSize: '14px',
      fontWeight: '600',
      color: '#6b7280',
      marginBottom: '8px',
    },
    select: {
      width: '100%',
      padding: '12px',
      borderRadius: '10px',
      border: '1px solid #e5e7eb',
      backgroundColor: '#f9fafb',
      fontSize: '15px',
      outline: 'none',
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))',
      gap: '30px',
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '0 20px 60px 20px',
    },
    card: {
      backgroundColor: 'white',
      borderRadius: '16px',
      padding: '25px',
      border: '1px solid #f3e8ff',
      boxShadow: '0 4px 6px rgba(0,0,0,0.02)',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-between'
    },
    tag: {
      backgroundColor: '#f3e8ff',
      color: '#7e22ce',
      padding: '4px 10px',
      borderRadius: '6px',
      fontSize: '12px',
      fontWeight: '600',
    },
    metaInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '8px',
      margin: '20px 0',
      borderTop: '1px solid #f3f4f6',
      paddingTop: '15px',
    },
    infoItem: {
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      fontSize: '14px',
      color: '#4b5563',
    },
    searchBtn: {
      backgroundColor: '#4a3f6b',
      color: 'white',
      padding: '12px 30px',
      borderRadius: '10px',
      border: 'none',
      fontWeight: 'bold',
      cursor: 'pointer',
      display: 'flex',
      alignItems: 'center',
      gap: '8px'
    },
    viewBtn: {
      backgroundColor: '#e9d5ff',
      color: '#6b21a8',
      padding: '12px',
      borderRadius: '10px',
      border: 'none',
      fontWeight: '600',
      cursor: 'pointer',
      transition: 'background 0.3s'
    }
  };

  const opportunitiesData = [
    { title: "Frontend Development", company: "Digital Innovation Co.", loc: "Constantine", dur: "3 Months", pay: "Paid", tags: ["React", "Tailwind"] },
    { title: "Data Analysis", company: "Advanced Data Group", loc: "Algiers", dur: "2 Months", pay: "Unpaid", tags: ["Python", "SQL"] },
    { title: "UI/UX Design", company: "Creative Agency", loc: "Oran", dur: "4 Months", pay: "Paid", tags: ["Figma", "Adobe"] }
  ];

  return (
    <div style={styles.container}>
      <section style={styles.heroSection}>
        <h1 style={styles.heroTitle}>Find Your Next Opportunity</h1>
        <p style={{ opacity: 0.9 }}>Your ultimate platform for internship and job opportunities.</p>
      </section>
      <div style={styles.filterContainer}>
        <div style={styles.inputGroup}>
          <label style={styles.label}>Wilaya</label>
          <select style={styles.select} value={filterWilaya} onChange={(e) => setFilterWilaya(e.target.value)}>
            <option value="">All Regions</option>
            {algeriaWilayas.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>
        <div style={styles.inputGroup}>
          <label style={styles.label}>Technology</label>
          <select style={styles.select} value={filterTech} onChange={(e) => setFilterTech(e.target.value)}>
            <option value="">All Tech</option>
            {techs.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <button style={styles.searchBtn}>
          <Search size={18} /> Search
        </button>
      </div>

      <div style={styles.grid}>
        {opportunitiesData.map((job, index) => (
          <div key={index} style={styles.card}>
            <div>
              <h3 style={{ color: '#4b2c5e', fontSize: '20px', fontWeight: 'bold' }}>{job.title}</h3>
              <p style={{ color: '#6b7280', fontSize: '14px', margin: '5px 0 15px 0' }}>{job.company}</p>
              
              <div style={{ display: 'flex', gap: '8px' }}>
                {job.tags.map(tag => <span key={tag} style={styles.tag}>{tag}</span>)}
              </div>

              <div style={styles.metaInfo}>
                <div style={styles.infoItem}><MapPin size={16} /> {job.loc}</div>
                <div style={styles.infoItem}><Clock size={16} /> {job.dur}</div>
                <div style={styles.infoItem}><Award size={16} /> {job.pay}</div>
              </div>
            </div>
            <button 
              style={styles.viewBtn}
              onMouseOver={(e) => e.target.style.backgroundColor = '#ddd6fe'}
              onMouseOut={(e) => e.target.style.backgroundColor = '#e9d5ff'}
            >
              View Details
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Opportunities;
